    /**
     * Tests getting all SimCards.
     *
     * @return    Collection
     */
    public List<SimCard> testGetAll() throws Throwable {
    LOGGER.info( "SimCardTest:testGetAll() - Retrieving Collection of SimCards:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all SimCard : " );
    List<SimCard> collection  = null;

    try {
        // call the static get method on the SimCardService
        collection = service.getAllSimCard();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            SimCard currEntity  = null;
            Iterator<SimCard> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSimCardId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

